// ============================================================================
// 00 - Config  (the ONLY place with limits, keywords and model settings; NO secrets here)
// Secrets live in n8n Credentials: "Firecrawl API" and "Gemini API" (Header Auth).
// Manual runs use the "test" preset, scheduled runs use "production".
// Set FORCE_PRESET to 'test' or 'production' to override.
// ============================================================================
const FORCE_PRESET = null;
const PRESET = FORCE_PRESET || ($execution.mode === 'test' ? 'test' : 'production');

const PRESETS = {
  test: {
    fmKeywordMode: 'quick',        // quick = 1 keyword | category_test = 1 per category | full = all keywords
    fmPagesPerKeyword: 1,
    fmMaxDetailPages: 5,           // 0 = scrape every tender found
    boampPagesPerType: 1,          // 100 records per page
    tnListPages: 1,
    tnMaxDetailPages: 3,           // 0 = all
    maxBuyersToEnrich: 5,          // 0 = all (France buyers, highest priority first)
    aiMaxTenders: 10               // 0 = all
  },
  production: {
    fmKeywordMode: 'full',
    fmPagesPerKeyword: 2,
    fmMaxDetailPages: 0,
    boampPagesPerType: 3,
    tnListPages: 3,
    tnMaxDetailPages: 0,
    maxBuyersToEnrich: 60,
    aiMaxTenders: 0
  }
};

// One taxonomy drives BOTH the France Marchés search keywords AND category classification for every source.
// Short acronyms (<=3 letters, or ALL-CAPS <=5) are matched case-sensitively to avoid "mode", "ai", "ml" style noise.
const taxonomy = {
  'Data': ['Data platform', 'plateforme de données', 'Data warehouse', 'entrepôt de données', 'Data lake', 'intégration de données', 'ETL', 'API REST', 'Middleware', 'interopérabilité'],
  'CRM / Customer Data': ['Salesforce', 'CRM', 'gestion de la relation client', 'Customer Data Platform', 'CDP', 'données clients'],
  'BI / Analytics': ['Business Intelligence', 'Power BI', 'outils de reporting', 'tableaux de bord', 'data analytics', 'décisionnel'],
  'AI': ['Artificial Intelligence', 'Intelligence Artificielle', 'IA', 'Machine Learning', 'apprentissage automatique', 'systèmes de recommandation', 'analyse prédictive', 'predictive analytics'],
  'E-commerce / Digital Commerce': ['E-commerce', 'commerce électronique', 'plateforme e-commerce', 'omnicanal', 'personnalisation client', 'commerce digital'],
  'Enterprise Software': ['ERP', 'SAP', 'MuleSoft', 'Talend', 'Boomi', 'Workato', 'progiciel de gestion intégré'],
  'Supply Chain': ['supply chain', 'chaîne logistique', 'prévision des ventes', 'prévision de la demande', 'gestion des stocks', 'demand forecasting', 'inventory management'],
  'Fashion / Retail': ['fashion retail', 'prêt-à-porter', 'textile', 'habillement', 'marketplace', 'détection de contrefaçon']
};

// Generic IT vocabulary: a tender whose TITLE matches one of these (or the taxonomy) passes the relevance gate.
const coreTerms = ['informatique', 'logiciel', 'logiciels', 'progiciel', "système d'information", "systèmes d'information", 'cloud', 'SaaS', 'cybersécurité', 'hébergement', 'infogérance', 'maintenance applicative', 'base de données', 'bases de données', 'application web', 'application mobile', 'site internet', 'numérique', 'dématérialisation', 'GED', 'SIRH'];

return [{ json: {
  preset: PRESET,
  today: new Date().toISOString().slice(0, 10),
  limits: PRESETS[PRESET],
  fm: { baseUrl: 'https://www.francemarches.com/recherche', pageParam: 'page' },   // verify pageParam on the site
  boamp: { types: ['SERVICES', 'FOURNITURES', 'TRAVAUX'], pageSize: 100 },
  tn: { listUrl: 'https://www.domainetat.tn/?cat=19&lang=fr', pageParam: 'paged', issuer: "Ministère des Domaines de l'État et des Affaires Foncières", requireKeywordMatch: true },
  includeAwards: false,
  taxonomy,
  coreTerms,
  enrichment: { registryMinSimilarity: 0.6 },
  gemini: { model: 'gemini-flash-latest' },
  companyProfile: 'A consultancy delivering data platforms and integration, CRM, BI/analytics, AI/ML, e-commerce/digital commerce, ERP/enterprise integration and supply-chain software, with a focus on retail and fashion.'
} }];

// Rows come from the (optional) Google Sheet. If that node is disabled, this receives the Config item and known_ids stays empty.
const known = new Set();
for (const it of $input.all()) { const id = it.json.tender_id; if (id) known.add(String(id)); }
return [{ json: { known_ids: Array.from(known), known_count: known.size } }];

const CFG = $('00 - Config').first().json;
const mode = CFG.limits.fmKeywordMode;
const tax = CFG.taxonomy;
let list = [];
if (mode === 'quick') list = [{ category: 'Enterprise Software', keyword: 'ERP' }];
else if (mode === 'category_test') { for (const [cat, kws] of Object.entries(tax)) list.push({ category: cat, keyword: kws[0] }); }
else { for (const [cat, kws] of Object.entries(tax)) for (const kw of kws) list.push({ category: cat, keyword: kw }); }

const out = [];
const pages = Math.max(1, CFG.limits.fmPagesPerKeyword);
for (const { category, keyword } of list) {
  for (let p = 1; p <= pages; p++) {
    let url = CFG.fm.baseUrl + '?q=' + encodeURIComponent(keyword) + '&etat=en-cours';
    if (p > 1) url += '&' + CFG.fm.pageParam + '=' + p;
    out.push({ json: { keyword, category, page: p, searchUrl: url } });
  }
}
return out;

// ---------- shared helpers (identical in every node that uses them) ----------
const CFG = $('00 - Config').first().json;
const TODAY_ISO = CFG.today;
const STOPWORDS = new Set(['de','du','des','la','le','les','et','d','l','sur','en','au','aux','a','pour']);
const GENERIC_ORG = new Set(['commune','ville','mairie','departement','conseil','region','communaute','agglomeration','metropole','syndicat','centre','etablissement','public','service','services','office','agence','ministere','direction','groupement','communes','intercommunal','intercommunale','regional','departemental']);

function stripAccents(s){ return String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
function normKey(s){ return stripAccents(s).toLowerCase().replace(/&#0?39;/g, "'").replace(/[^a-z0-9]+/g, ' ').trim(); }
function normFlat(s){ return normKey(s).replace(/ /g, ''); }
function escRe(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function clean(s){ return String(s == null ? '' : s).replace(/&#0?39;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim(); }

const MONTHS = { janvier:1, fevrier:2, mars:3, avril:4, mai:5, juin:6, juillet:7, aout:8, septembre:9, octobre:10, novembre:11, decembre:12 };
function pad2(n){ return String(n).padStart(2, '0'); }
function validYMD(y, m, d){ return y >= 2000 && y <= 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31; }
// Converts ISO, dd/mm/yyyy, dd-mm-yyyy and French text ("20 août 2026") to yyyy-mm-dd. Returns '' if unparsable.
function toISO(v){
  if (v === null || v === undefined || v === '') return '';
  if (v instanceof Date && !isNaN(v)) return v.toISOString().slice(0, 10);
  const s = String(v).trim();
  let m = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m && validYMD(+m[1], +m[2], +m[3])) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})/);
  if (m && validYMD(+m[3], +m[2], +m[1])) return m[3] + '-' + pad2(m[2]) + '-' + pad2(m[1]);
  m = stripAccents(s).toLowerCase().match(/(\d{1,2})(?:er)?\s+([a-z]+)\s+(\d{4})/);
  if (m && MONTHS[m[2]] && validYMD(+m[3], MONTHS[m[2]], +m[1])) return m[3] + '-' + pad2(MONTHS[m[2]]) + '-' + pad2(m[1]);
  return '';
}
function daysUntil(iso){
  if (!iso) return null;
  return Math.round((new Date(iso + 'T00:00:00Z') - new Date(TODAY_ISO + 'T00:00:00Z')) / 86400000);
}

// ---------- keyword matching (one taxonomy, defined in the Config node) ----------
function buildMatcher(pairs){
  return pairs.map(({ category, kw }) => {
    const cs = kw.length <= 3 || (kw === kw.toUpperCase() && /[A-Z]/.test(kw) && kw.length <= 5);
    const pat = escRe(cs ? kw : stripAccents(kw).toLowerCase());
    return { category, kw, cs, re: new RegExp('(^|[^A-Za-z0-9])' + pat + '([^A-Za-z0-9]|$)') };
  });
}
const TAXO = buildMatcher(Object.entries(CFG.taxonomy).flatMap(([category, kws]) => kws.map(kw => ({ category, kw }))));
const CORE = buildMatcher(CFG.coreTerms.map(kw => ({ category: 'IT - Other', kw })));
function matchAll(matchers, text){
  const raw = String(text || '').replace(/\s+/g, ' ');
  const folded = stripAccents(raw).toLowerCase();
  const hits = [];
  for (const m of matchers) { if (m.re.test(m.cs ? raw : folded)) hits.push(m); }
  return hits;
}
function classify(text){
  const raw = String(text || '');
  // "CRM" is also a French driver-training diploma (Conducteur Routier Marchandises): not a CRM software tender
  const driverTraining = /\b(?:bac\s*pro|cap)\s*crm\b/i.test(raw) && !/salesforce|hubspot|zendesk|dynamics|client/i.test(raw);
  const cats = [];
  for (const h of matchAll(TAXO, raw)) {
    if (h.category === 'CRM / Customer Data' && driverTraining) continue;
    if (!cats.includes(h.category)) cats.push(h.category);
  }
  return cats;
}
function isRelevant(text){ return classify(text).length > 0 || matchAll(CORE, text).length > 0; }

const PORTAL_RE = /(francemarches|boamp|marches-publics|marchespublics|achatpublic|e-marchespublics|aws-achat|maximilien|klekoon|dematis|marches-securises|marchesonline|domainetat\.tn|megalis|approlys|proxylis|webmarche|atexo|centraledesmarches|synapse-entreprises)/i;
function isPortal(url){ return !!url && PORTAL_RE.test(String(url)); }
function hostOf(url){ try { return new URL(url).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; } }

function buyerName(t){ return clean((t.buyer_information && t.buyer_information.name) || t.issuer || ''); }
function buyerKey(t){
  const n = normFlat(buyerName(t));
  return (t.country || 'unknown') + ':' + ((!n || n === 'nonspecifie') ? 'unknown' : n);
}

// 64-bit non-cryptographic hash (no require('crypto') needed)
function hash(str){
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}

const items = $input.all();
const map = new Map();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  if (j.error) continue;                       // failed page: skipped here, counted in the run summary
  const markdown = (j.data || j).markdown || '';
  if (!markdown) continue;

  let searchCategory = '';
  try { searchCategory = $('FM1 - Build Search Requests').itemMatching(i).json.category || ''; } catch (e) {}

  // France Marchés card: [001\ ... **Title** ... Date parution : ...](https://www.francemarches.com/appel-offre/<slug>)
  const cardRegex = /\[([0-9]{3}\\?[\s\S]*?)\]\((https?:\/\/[^\s\)]*francemarches\.com\/appel-offre\/[^\s\)]+)\)/g;
  let match;
  while ((match = cardRegex.exec(markdown)) !== null) {
    const source_url = match[2].split('?')[0];
    const cleanBody = match[1].replace(/\\/g, '').trim();

    const titleMatch = cleanBody.match(/\*\*([^*]+)\*\*/);
    const title = titleMatch ? clean(titleMatch[1]) : '';
    if (!title) continue;
    if (!isRelevant(title)) continue;           // shared relevance gate, on the TITLE only (kills "mode", "retail" style noise)

    const slug = source_url.split('/appel-offre/')[1] || '';
    const refMatch = slug.match(/^([a-zA-Z0-9]+-[0-9]{4})/);
    const reference = refMatch ? refMatch[1] : (slug.split('-')[0] || slug);

    const idxTitle = cleanBody.indexOf('**' + title + '**');
    let issuer = '';
    if (idxTitle > 0) {
      const lines = cleanBody.substring(0, idxTitle).split('\n').map(l => l.trim())
        .filter(l => l && !/^[0-9]+$/.test(l) && !l.startsWith('![') && !l.startsWith('[!'));
      if (lines.length) issuer = clean(lines[lines.length - 1]);
    }
    const parution = cleanBody.match(/Date parution\s*:\s*([0-9]{2}\/[0-9]{2}\/[0-9]{4})/i);
    const cloture = cleanBody.match(/Date cl[ôo]t[ûu]re\s*:\s*\*?\*?([0-9]{2}\/[0-9]{2}\/[0-9]{4})\*?\*?/i);

    const key = reference || source_url;
    if (map.has(key)) continue;
    map.set(key, {
      source_key: 'francemarches', source_id: reference, reference, title, issuer,
      date: parution ? parution[1] : '', deadline: cloture ? cloture[1] : '',
      raw_text: cleanBody.replace(/\s+/g, ' ').trim(), source_url, search_category: searchCategory
    });
  }
}
return Array.from(map.values()).map(t => ({ json: t }));

// Detail-page limit comes from the Config node (0 = scrape every tender found).
const CFG = $('00 - Config').first().json;
const max = Number(CFG.limits.fmMaxDetailPages || 0);
const items = $input.all();
return (max > 0 && items.length > max) ? items.slice(0, max) : items;

