function normFlat(s){ return normKey(s).replace(/ /g, ''); }
function escRe(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function clean(s){ return String(s == null ? '' : s).replace(/&#0?39;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim(); }

const MONTHS = { janvier:1, fevrier:2, mars:3, avril:4, mai:5, juin:6, juillet:7, aout:8, septembre:9, octobre:10, novembre:11, decembre:12 };
function pad2(n){ return String(n).padStart(2, '0'); }
function validYMD(y, m, d){ return y >= 2000 && y <= 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31; }
// Converts ISO, dd/mm/yyyy, dd-mm-yyyy and French text ("20 août 2026") to yyyy-mm-dd. Returns '' if unparsable.
function toISO(v){
  if (v === null || v === undefined || v === '') return '';
  if (v instanceof Date && !isNaN(v)) return v.toISOString().slice(0, 10);
  const s = String(v).trim();
  let m = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m && validYMD(+m[1], +m[2], +m[3])) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})/);
  if (m && validYMD(+m[3], +m[2], +m[1])) return m[3] + '-' + pad2(m[2]) + '-' + pad2(m[1]);
  m = stripAccents(s).toLowerCase().match(/(\d{1,2})(?:er)?\s+([a-z]+)\s+(\d{4})/);
  if (m && MONTHS[m[2]] && validYMD(+m[3], MONTHS[m[2]], +m[1])) return m[3] + '-' + pad2(MONTHS[m[2]]) + '-' + pad2(m[1]);
  return '';
}
function daysUntil(iso){
  if (!iso) return null;
  return Math.round((new Date(iso + 'T00:00:00Z') - new Date(TODAY_ISO + 'T00:00:00Z')) / 86400000);
}

// ---------- keyword matching (one taxonomy, defined in the Config node) ----------
function buildMatcher(pairs){
  return pairs.map(({ category, kw }) => {
    const cs = kw.length <= 3 || (kw === kw.toUpperCase() && /[A-Z]/.test(kw) && kw.length <= 5);
    const pat = escRe(cs ? kw : stripAccents(kw).toLowerCase());
    return { category, kw, cs, re: new RegExp('(^|[^A-Za-z0-9])' + pat + '([^A-Za-z0-9]|$)') };
  });
}
const TAXO = buildMatcher(Object.entries(CFG.taxonomy).flatMap(([category, kws]) => kws.map(kw => ({ category, kw }))));
const CORE = buildMatcher(CFG.coreTerms.map(kw => ({ category: 'IT - Other', kw })));
function matchAll(matchers, text){
  const raw = String(text || '').replace(/\s+/g, ' ');
  const folded = stripAccents(raw).toLowerCase();
  const hits = [];
  for (const m of matchers) { if (m.re.test(m.cs ? raw : folded)) hits.push(m); }
  return hits;
}
function classify(text){
  const raw = String(text || '');
  // "CRM" is also a French driver-training diploma (Conducteur Routier Marchandises): not a CRM software tender
  const driverTraining = /\b(?:bac\s*pro|cap)\s*crm\b/i.test(raw) && !/salesforce|hubspot|zendesk|dynamics|client/i.test(raw);
  const cats = [];
  for (const h of matchAll(TAXO, raw)) {
    if (h.category === 'CRM / Customer Data' && driverTraining) continue;
    if (!cats.includes(h.category)) cats.push(h.category);
  }
  return cats;
}
function isRelevant(text){ return classify(text).length > 0 || matchAll(CORE, text).length > 0; }

