const buyers = new Map();
for (const it of $input.all()) buyers.set(it.json.buyer_key, it.json);
const tenders = $('Dedupe & Assign IDs').all().map(i => i.json);

const out = tenders.map(t => {
  const b = buyers.get(buyerKey(t)) || null;
  const bi = { ...(t.buyer_information || {}) };
  const tenderHad = { email: !!bi.email, phone: !!bi.phone, website: !!bi.website };
  const contact_source = {}, contact_status = {};
  const attempted = b && ['enriched', 'attempted_no_data'].includes(b.enrichment_status);

  for (const f of ['email', 'phone', 'website']) {
    if (tenderHad[f]) { contact_source[f] = 'tender_notice'; contact_status[f] = 'found_in_notice'; continue; }
    const v = b && b.contacts ? b.contacts[f] : '';
    if (v) { bi[f] = v; contact_source[f] = (b.contact_sources && b.contact_sources[f]) || ''; contact_status[f] = 'found_web'; }
    else contact_status[f] = attempted ? 'not_found' : 'not_attempted';
  }
  if (b && b.contacts) { if (!bi.address && b.contacts.address) bi.address = b.contacts.address; if (!bi.legal_form && b.contacts.legal_form) bi.legal_form = b.contacts.legal_form; }

  // never list the tender itself as one of the buyer's "past projects"
  const ownIds = new Set((t.sources || []).map(s => String(s.source_id)));
  const past_projects = ((b && b.past_projects) || []).filter(p => !(p.id && ownIds.has(String(p.id))) && normFlat(p.title) !== normFlat(t.title));
  const org = (b && b.org_profile) || null;

  return { json: {
    ...t,
    buyer_information: bi, contact_source, contact_status,
    legal_name: b && b.registry ? b.registry.legal_name : '',
    siret: b && b.registry ? b.registry.siret : '',
    enrichment_status: b ? b.enrichment_status : 'not_attempted',
    buyer_profile: {
      client_identified: b ? !!b.client_identified : false,
      registry_match: b && b.registry ? { ok: b.registry.match_ok, score: b.registry.score, reason: b.registry.reason } : null,
      sector: org ? org.sector : null, organization_description: org ? org.organization_description : null, scale: org ? org.scale : null,
      past_digital_projects: org ? org.past_digital_projects : [],
      key_partners: org ? org.institutional_partners : [],          // institutional partners only
      past_suppliers: (b && b.past_suppliers) || [],                 // BOAMP/DECP suppliers, kept separate on purpose
      past_projects,
      evidence_confidence: org ? org.evidence_confidence : null,
      ai_status: b ? (b.ai_status || 'n/a') : 'n/a'
    }
  } };
});
return out;

