}

// 64-bit non-cryptographic hash (no require('crypto') needed)
function hash(str){
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}


function parseGemini(resp){
  if (!resp) return { ok: false, error: 'empty response' };
  if (resp.error) return { ok: false, error: typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error)).slice(0, 300) };
  const parts = (((resp.candidates || [])[0] || {}).content || {}).parts || [];
  let text = parts.map(p => p.text || '').join('').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  if (!text) return { ok: false, error: 'Gemini returned no text (finish reason: ' + ((resp.candidates || [])[0] || {}).finishReason + ')' };
  try { return { ok: true, data: JSON.parse(text) }; } catch (e) {}
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { return { ok: true, data: JSON.parse(m[0]) }; } catch (e) {} }
  return { ok: false, error: 'Unparseable Gemini output: ' + text.slice(0, 120) };
}
function geminiBody(system, user, maxTokens){
  return {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.1, responseMimeType: 'application/json', maxOutputTokens: maxTokens || 4096 }
  };
}

