  const r = (d && d.requirements) || {};

  const analysis = d ? {
    relevance_score: Math.max(0, Math.min(100, Math.round(Number(d.relevance_score) || 0))),
    relevance_rationale: d.relevance_rationale || '',
    matched_service_lines: arr(d.matched_service_lines),
    suggested_angle: d.suggested_angle || '',
    risks: arr(d.risks),
    sector: d.sector || null,
    requirements: {
      technical: toList(r.technical),
      team: toList(r.team),
      experience: toList(r.experience),
      timeline: r.timeline ? String(r.timeline).trim() : null
    }
  } : null;

  const { _gemini_body, ...rest } = t;
  out.push({ json: { ...rest, analysis, analysis_status: p.ok ? 'OK' : 'Error: ' + p.error } });
}
return out;

