    return { category, kw, cs, re: new RegExp('(^|[^A-Za-z0-9])' + pat + '([^A-Za-z0-9]|$)') };
  });
}
const TAXO = buildMatcher(Object.entries(CFG.taxonomy).flatMap(([category, kws]) => kws.map(kw => ({ category, kw }))));
const CORE = buildMatcher(CFG.coreTerms.map(kw => ({ category: 'IT - Other', kw })));
function matchAll(matchers, text){
  const raw = String(text || '').replace(/\s+/g, ' ');
  const folded = stripAccents(raw).toLowerCase();
  const hits = [];
  for (const m of matchers) { if (m.re.test(m.cs ? raw : folded)) hits.push(m); }
  return hits;
}
function classify(text){
  const raw = String(text || '');
  // "CRM" is also a French driver-training diploma (Conducteur Routier Marchandises): not a CRM software tender
  const driverTraining = /\b(?:bac\s*pro|cap)\s*crm\b/i.test(raw) && !/salesforce|hubspot|zendesk|dynamics|client/i.test(raw);
  const cats = [];
  for (const h of matchAll(TAXO, raw)) {
    if (h.category === 'CRM / Customer Data' && driverTraining) continue;
    if (!cats.includes(h.category)) cats.push(h.category);
  }
  return cats;
}
function isRelevant(text){ return classify(text).length > 0 || matchAll(CORE, text).length > 0; }

const PORTAL_RE = /(francemarches|boamp|marches-publics|marchespublics|achatpublic|e-marchespublics|aws-achat|maximilien|klekoon|dematis|marches-securises|marchesonline|domainetat\.tn|megalis|approlys|proxylis|webmarche|atexo|centraledesmarches|synapse-entreprises)/i;
function isPortal(url){ return !!url && PORTAL_RE.test(String(url)); }
function hostOf(url){ try { return new URL(url).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; } }

function buyerName(t){ return clean((t.buyer_information && t.buyer_information.name) || t.issuer || ''); }
function buyerKey(t){
  const n = normFlat(buyerName(t));
  return (t.country || 'unknown') + ':' + ((!n || n === 'nonspecifie') ? 'unknown' : n);
}

// 64-bit non-cryptographic hash (no require('crypto') needed)
function hash(str){
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}

const items = $input.all().map(i => i.json);

function urgencyPts(d){ if (d === null || d === undefined) return 40; if (d < 0) return 0; if (d <= 3) return 35; if (d <= 14) return 100; if (d <= 30) return 80; if (d <= 60) return 55; return 35; }
function stripInternal(v){
  if (Array.isArray(v)) return v.map(stripInternal);
  if (v && typeof v === 'object') { const o = {}; for (const [k, x] of Object.entries(v)) { if (k.startsWith('_')) continue; o[k] = stripInternal(x); } return o; }
  return v;
}

const tenders = items.map(t => {
  const a = t.analysis || null;
