  const relevance = a ? a.relevance_score : Math.min(100, Math.round((t.heuristic_score || 0) * 100 / 75));
  const evidence = Math.round(((t.buyer_profile && t.buyer_profile.client_identified) ? 60 : 20) + contactsFound * 13);
  const priority_score = Math.round(0.6 * relevance + 0.25 * urgencyPts(t.days_to_deadline) + 0.15 * Math.min(100, evidence));
  const priority = priority_score >= 70 ? 'high' : (priority_score >= 45 ? 'medium' : 'low');
  const { do_ai, raw_text, ...rest } = t;
  return stripInternal({
    ...rest,
    analysis_status: t.analysis_status || 'not_attempted',
    relevance_score: relevance, relevance_basis: a ? 'gemini' : 'heuristic', priority_score, priority
  });
}).sort((x, y) => y.priority_score - x.priority_score);

const DQ = String.fromCharCode(34);
const esc = v => { if (v === null || v === undefined) return DQ + DQ; return DQ + String(v).replace(/[\r\n]+/g, ' ').replace(new RegExp(DQ, 'g'), DQ + DQ) + DQ; };
